// ===================== CONFIG — Lembrete diário de O.S. paradas =====================
// ENVIO: 'NENHUM'  -> só monta (confira a saída do nó "Montar mensagens")
//        'SIMULAR' -> manda só para RESUMO_PARA: o resumo + até 3 mensagens de amostra
//        'REAL'    -> manda para os técnicos + resumo para RESUMO_PARA
const ENVIO = 'REAL';
const RESUMO_PARA = '55__TELEFONE__';            // seu WhatsApp, ex.: '55__TELEFONE__' (vazio = sem resumo)
const WAHA_SESSION = 'session_01m4xy9khpbqgnafzqhd9wchx1';

const DIAS_SEM_REGISTRO = 2;       // parado = sem mensagem na O.S. há N dias
const STATUS_PARADO = ['EN', 'AG', 'AN'];
const MAX_LINHAS_POR_TECNICO = 20; // acima disso: "... e mais N"
const MAX_MENSAGENS_DIA = 40;      // trava de segurança anti-bloqueio
const FORCAR_REENVIO_HOJE = false; // true = permite 2º envio REAL no mesmo dia

// Assuntos: ativação (5) + documentação (último)
const ASSUNTOS = {
  RESOLUTTO: [69, 83, 84, 86, 94, 85,30,14],
  '4B':      [89, 90, 91, 93, 98, 92,86,0],
  PONTO:     [65, 63, 62, 61, 70, 64,52,0],
  CACTA:     [73, 74, 77, 75, 81, 76,68,0],
  BUZZ:      [83, 84, 85, 87, 91, 86,80,0],
};

// Pessoa -> WhatsApp e id de colaborador EM CADA BASE (ids mudam por base).
// whatsapp vazio = não recebe (aparece no resumo como "sem WhatsApp").
const PESSOAS = [
  { nome: 'Técnico 6',            whatsapp: '55__TELEFONE__',             ids: { RESOLUTTO: [6],  CACTA: [6] } },
  { nome: 'Técnico 12',           whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [12], '4B': [12] } },
  { nome: 'Técnico 13',                     whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [13], CACTA: [13] } },
  { nome: 'Técnico 16',        whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [16], '4B': [16] } },
  { nome: 'Técnico 17',          whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [17], PONTO: [17] } },
  { nome: 'Técnico 18',       whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [18], '4B': [18] } },
  { nome: 'Técnico 20',          whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [20], PONTO: [20] } },
  { nome: 'Técnico 21',                    whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [21], PONTO: [21] } },
  { nome: 'Técnico 22',         whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [22], '4B': [22], PONTO: [22], CACTA: [22], BUZZ: [22] } },
  { nome: 'Técnico 25',             whatsapp: '55__TELEFONE__',             ids: { RESOLUTTO: [25], '4B': [25] } },
  { nome: 'Técnico 31',            whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [31], CACTA: [31] } },
  { nome: 'Técnico 56',             whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [56], PONTO: [62] } },
  { nome: 'Técnico 52',           whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [52], '4B': [46], PONTO: [52], CACTA: [62], BUZZ: [58] } },
  { nome: 'Técnico 32',          whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [32], CACTA: [32] } },
  { nome: 'Técnico 54',            whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [54], CACTA: [46] } },
  { nome: 'Técnico 51',       whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [51], '4B': [61], PONTO: [59], CACTA: [49], BUZZ: [60] } },
  { nome: 'Técnico 35',                  whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [35], CACTA: [35] } },
  { nome: 'Técnico 37',         whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [37], PONTO: [37] } },
  { nome: 'Técnico 55',     whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [55], '4B': [48] } },
  { nome: 'Técnico 38', whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [38], CACTA: [38] } },
  { nome: 'Técnico 48',             whatsapp: '',             ids: { RESOLUTTO: [48] } },
  { nome: 'Técnico 57',           whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [57], BUZZ: [46] } },
  { nome: 'Técnico 41',   whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [41], '4B': [41] } },
  { nome: 'Técnico 42',             whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [42], '4B': [42], PONTO: [42], CACTA: [42], BUZZ: [42] } },
  { nome: 'Técnico PONTO-61',    whatsapp: '55__TELEFONE__', ids: { PONTO: [61] } },
  { nome: 'Técnico 43',         whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [43], '4B': [43], PONTO: [43], CACTA: [43], BUZZ: [43] } },
  { nome: 'Técnico 44',   whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [44], CACTA: [44] } }, // RESOLUTTO 44 marcado com (?) na lista
  { nome: 'Técnico 45',    whatsapp: '55__TELEFONE__', ids: { RESOLUTTO: [45], '4B': [45] } },
];
// =====================================================================================

const BASES = ['RESOLUTTO', '4B', 'PONTO', 'CACTA', 'BUZZ'];
const agora = DateTime.now().setZone('America/Sao_Paulo');
const LIMITE = agora.minus({ days: DIAS_SEM_REGISTRO }).toFormat('yyyy-MM-dd HH:mm:ss');

// Validações que travam o workflow (melhor parar do que avisar a pessoa errada)
const erros = [];
const visto = {};
for (const p of PESSOAS) {
  for (const [b, ids] of Object.entries(p.ids)) {
    if (!BASES.includes(b)) erros.push(`${p.nome}: base desconhecida ${b}`);
    for (const id of ids) {
      const k = `${b}:${id}`;
      if (visto[k]) erros.push(`id ${id} da base ${b} aparece em ${visto[k]} e ${p.nome}`);
      visto[k] = p.nome;
    }
  }
  if (p.whatsapp && !/^55\d{10,11}$/.test(p.whatsapp)) erros.push(`${p.nome}: WhatsApp inválido ${p.whatsapp}`);
}
if (!['NENHUM', 'SIMULAR', 'REAL'].includes(ENVIO)) erros.push(`ENVIO inválido: ${ENVIO}`);
if (ENVIO === 'SIMULAR' && !RESUMO_PARA) erros.push('ENVIO SIMULAR exige RESUMO_PARA');
const qtd = new Set(BASES.map(b => (ASSUNTOS[b] || []).length));
if (qtd.size !== 1) erros.push('Todas as bases precisam ter o mesmo número de assuntos em ASSUNTOS');
if (erros.length) throw new Error('Config inválida: ' + erros.join(' | '));

const cfg = {
  ENVIO, RESUMO_PARA, WAHA_SESSION, DIAS_SEM_REGISTRO, STATUS_PARADO,
  MAX_LINHAS_POR_TECNICO, MAX_MENSAGENS_DIA, FORCAR_REENVIO_HOJE,
  ASSUNTOS, PESSOAS, BASES, LIMITE,
  HOJE: agora.toFormat('yyyy-MM-dd'), AGORA: agora.toFormat('dd/MM HH:mm'),
};
// Um item por assunto (índice): os nós "OS <BASE>" fazem uma chamada por item.
return ASSUNTOS.RESOLUTTO.map((_, i) => ({ json: { indice: i, ...(i === 0 ? { cfg } : {}) } }));

// Monta 1 mensagem por técnico (todas as bases juntas) + o resumo.
// ===== AUSÊNCIAS (férias, folga, atestado...) — quem estiver aqui NÃO recebe aviso =====
// pessoa: nome como está em PESSOAS (pode ser o começo do nome, se for único: 'Técnico 42')
// de / ate: AAAA-MM-DD ou DD/MM/AAAA (os dois dias entram). Sem 'ate' = até alguém tirar da lista.
const AUSENCIAS = [
    //{ pessoa: 'Técnico 42', de: '15/10/2026', ate: '15/10/2026', motivo: 'Teste' },
  // { pessoa: 'Técnico 17', de: '17/10/2026', ate: '17/10/2026', motivo: 'Folga' },
];
const cfg = $('Config').first().json.cfg;
const { BASES, ASSUNTOS, PESSOAS, LIMITE } = cfg;

// Regras do aviso:
//  - status em STATUS_SEM_REGISTRO e sem mensagem há DIAS_SEM_REGISTRO dias -> "atualize e use o botão de agendamento"
//  - status AGENDADA com data de agendamento ANTERIOR A HOJE (ou sem data) -> "faça um novo agendamento"
//  - status AGENDADA com agendamento de hoje em diante -> ignorada
const STATUS_SEM_REGISTRO = ['EN'];   // para incluir "Em análise" também: ['EN', 'AN']
const STATUS_AGENDADA = 'AG';
const STATUS_NOME = { EN: 'Encaminhada', AG: 'Agendada', AN: 'Em análise' };
const HOJE_INI = DateTime.now().setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd') + ' 00:00:00';
const dataValida = s => !!(s && s.length >= 10 && !s.startsWith('0000'));
const fmtDataHora = s => dataValida(s) ? `${s.slice(8, 10)}/${s.slice(5, 7)}${s.length >= 16 && s.slice(11, 16) !== '00:00' ? ' ' + s.slice(11, 16) : ''}` : 'sem data';
// ===== Escala (planilha "Quem trabalha hoje") =====
// Só as pessoas abaixo dependem da escala; as demais recebem sempre.
// chaves = como o nome aparece na planilha (sem acento, maiúsculas, palavra inteira).
const ESCALA = [
  { pessoa: 'Técnico 25',             chaves: ['Técnico 25'] },          // PALLADIUM CURITIBA - Técnico 25
  { pessoa: 'Técnico 18',       chaves: ['Técnico 18'] },       // PALLADIUM CURITIBA - Técnico 18
  { pessoa: 'Técnico 32',          chaves: ['Técnico 32'] },   // JOCKEY - Técnico 32
  { pessoa: 'Técnico 54',            chaves: ['Técnico 54'] },       // JOCKEY - Técnico 54
  { pessoa: 'Técnico 45',    chaves: ['Técnico 45'] },          // FOZ - Técnico 45
  { pessoa: 'Técnico 55',     chaves: ['Técnico 55'] },          // FOZ - Técnico 55
  { pessoa: 'Técnico 31',            chaves: ['Técnico 31'] }, // CASCAVEL - Técnico 31
  { pessoa: 'Técnico 38', chaves: ['Técnico 38'] },        // CASCAVEL - Técnico 38
  { pessoa: 'Técnico 21',                    chaves: ['Técnico 21'] },        // quadro Porto Belo e Tijucas
  { pessoa: 'Técnico 56',             chaves: ['Técnico 56'] },    // quadro Porto Belo e Tijucas
];
const norm = t => String(t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
function parseCSV(txt) {
  const rows = []; let row = [], cell = '', q = false;
  for (let i = 0; i < txt.length; i++) {
    const c = txt[i];
    if (q) { if (c === '"') { if (txt[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && txt[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
  return rows;
}
// Lê a planilha: devolve { ok, trabalhando: Set(pessoa), detalhe } — ok=false se não der para confiar nela
function lerEscala() {
  const it = $('Escala').first();
  const j = (it && it.json) || {};
  if (j.error) return { ok: false, detalhe: 'planilha não lida: ' + (j.error.message || j.error) };
  const txt = typeof j.data === 'string' ? j.data : '';
  if (!txt || /<html/i.test(txt.slice(0, 200))) return { ok: false, detalhe: 'planilha não lida (link CSV inválido ou não publicado)' };
  const g = parseCSV(txt);
  const acha = re => { for (let r = 0; r < g.length; r++) for (let c = 0; c < g[r].length; c++) if (re.test(norm(g[r][c]))) return [r, c]; return null; };
  const pos = acha(/QUEM TRABALHA HOJE/);
  if (!pos) return { ok: false, detalhe: 'planilha sem o quadro "QUEM TRABALHA HOJE"' };
  const [r0, c0] = pos;
  let data = null;
  for (let c = c0; c < Math.min(c0 + 4, g[r0].length); c++) { const m = norm(g[r0][c]).match(/(\d{1,2})\/(\d{1,2})/); if (m) { data = m[1].padStart(2, '0') + '/' + m[2].padStart(2, '0'); break; } }
  const hoje = DateTime.now().setZone('America/Sao_Paulo').toFormat('dd/MM');
  if (data !== hoje) return { ok: false, detalhe: `planilha desatualizada: "Quem trabalha hoje" está com data ${data || '(sem data)'}, hoje é ${hoje}` };
  const linhas = [];
  for (let r = r0 + 1; r < Math.min(r0 + 20, g.length); r++) { const v = norm(g[r][c0]); if (!v) { if (linhas.length) break; else continue; } if (/QUEM TRABALHA/.test(v)) break; linhas.push(v); }
  const pb = acha(/HOJE EM PORTO BELO/);
  let portoBelo = '';
  if (pb) for (let r = pb[0] + 1; r < Math.min(pb[0] + 4, g.length); r++) { const v = norm(g[r][pb[1]]); if (v) { portoBelo = v; break; } }
  const texto = ' ' + [...linhas, portoBelo].join(' | ') + ' ';
  const trabalhando = new Set(ESCALA.filter(e => e.chaves.some(k => new RegExp(`[^A-Z]${norm(k)}[^A-Z]`).test(texto))).map(e => e.pessoa));
  return { ok: true, trabalhando, detalhe: `escala ${data}: ${linhas.join(' / ')}${portoBelo ? ' / Porto Belo e Tijucas: ' + portoBelo : ' / (quadro Porto Belo e Tijucas não encontrado)'}` };
}

// Link de acesso de cada base (só vão na mensagem as bases que o técnico tem O.S. parada)
const LINKS = {
  RESOLUTTO: 'https://ixc.resolutto.com.br/app/login',
  '4B':      'https://ixc.4btelecom.com.br/app/login',
  PONTO:     'https://ixc.pontotelecom.com/app/login',
  CACTA:     'https://ixc.cactatelecom.com.br/app/login',
  BUZZ:      'https://ixc.buzztelecom.com.br/app/login',
};

function parse(item) {
  const j = (item && item.json) || {};
  if (j.error) return { erro: String(j.error.message || j.error) };
  let d = j.data !== undefined ? j.data : j;
  if (typeof d === 'string') {
    try { d = JSON.parse(d.replace(/[\u0000-\u001F]+/g, ' ')); }
    catch (e) { return { erro: 'resposta não é JSON: ' + d.slice(0, 120) }; }
  }
  if (d && d.type === 'error') return { erro: String(d.message || 'erro da API') };
  return { total: Number(d.total || 0), registros: Array.isArray(d.registros) ? d.registros : [] };
}
const fmtData = s => (s && s.length >= 10 && !s.startsWith('0000')) ? `${s.slice(8, 10)}/${s.slice(5, 7)}` : '?';

// índice base:id -> pessoa
const porId = {};
for (const p of PESSOAS) for (const [b, ids] of Object.entries(p.ids)) for (const id of ids) porId[`${b}:${id}`] = p;

const panorama = { limite_sem_registro: LIMITE, por_base: {}, avisos: [] };
const linhasPorPessoa = new Map();   // pessoa -> [linhas]
const semCadastro = {};              // "BASE id" -> {nome, qtd}

for (const base of BASES) {
  const pb = panorama.por_base[base] = { lidas: 0, paradas: 0, erro: null };
  // 1) O.S. dos assuntos
  const osItems = $(`OS ${base}`).all();
  const os = [];
  let erroOS = null;
  osItems.forEach((it, i) => {
    const r = parse(it);
    if (r.erro) { erroOS = `assunto ${ASSUNTOS[base][i]}: ${r.erro}`; return; }
    if (r.total > r.registros.length) panorama.avisos.push(`${base} assunto ${ASSUNTOS[base][i]}: ${r.total} O.S., lidas só ${r.registros.length} (aumentar rp)`);
    os.push(...r.registros);
  });
  // 2) mensagens recentes (O.S. com registro depois do LIMITE não estão paradas)
  const rm = parse($(`Msg ${base}`).first());
  // 3) nomes de colaboradores e assuntos (só para deixar o texto legível)
  const rf = parse($(`Func ${base}`).first());
  const ra = parse($(`Assuntos ${base}`).first());
  if (erroOS || rm.erro) { pb.erro = erroOS || ('mensagens: ' + rm.erro); continue; } // base pulada inteira
  if (rm.total > rm.registros.length) { pb.erro = `mensagens: ${rm.total} registros, lidos ${rm.registros.length} (aumentar rp)`; continue; }
  if (rm.registros.length && rm.registros[0].id_chamado === undefined) { pb.erro = 'mensagens sem campo id_chamado: ' + Object.keys(rm.registros[0]).join(','); continue; }

  const recentes = new Set(rm.registros.map(m => String(m.id_chamado)));
  const nomeFunc = {}; (rf.registros || []).forEach(f => nomeFunc[String(f.id)] = f.funcionario || f.nome);

     const nomeAssunto = {}; (ra.registros || []).forEach(a => nomeAssunto[String(a.id)] = a.assunto || a.descricao);
    if (ra.erro || rf.erro) panorama.avisos.push(`${base}: nomes de ${ra.erro ? 'assunto' : 'colaborador'} não lidos (${ra.erro || rf.erro})`);
const nomeCliente = {};
  try { $(`Cliente ${base}`).all().forEach(it => { const c = (parse(it).registros || [])[0]; if (c && c.id) nomeCliente[String(c.id)] = String(c.fantasia || c.razao || '').trim(); }); }
  catch (e) { if (!panorama.avisos.includes('nós "Cliente <BASE>" não encontrados — mensagens sem nome do cliente')) panorama.avisos.push('nós "Cliente <BASE>" não encontrados — mensagens sem nome do cliente'); }




  const vistos = new Set();
  for (const o of os) {
    const id = String(o.id);
    if (vistos.has(id)) continue; vistos.add(id);
    pb.lidas++;
    const tec = String(o.id_tecnico || '0');
    if (tec === '0') continue;
    let tipo = null, detalhe = '';
    if (STATUS_SEM_REGISTRO.includes(o.status)) {
      if (recentes.has(id)) continue;                                                // teve registro recente
      if (dataValida(o.data_abertura) && o.data_abertura > LIMITE) continue;         // aberta há pouco
      tipo = 'sem_registro'; detalhe = `${o.status === 'EN' ? '' : (STATUS_NOME[o.status] || o.status) + ' · '}aberta ${fmtData(o.data_abertura)}`;
    } else if (o.status === STATUS_AGENDADA) {
      if (dataValida(o.data_agenda) && o.data_agenda >= HOJE_INI) continue;         // agendamento em dia
      tipo = 'agenda_vencida'; detalhe = dataValida(o.data_agenda) ? `agendada p/ ${fmtDataHora(o.data_agenda)}` : 'agendada sem data';
    } else continue;
    pb.paradas++;
    pb[tipo] = (pb[tipo] || 0) + 1;
    const linha = {
      base, os: id, tipo, abertura: o.data_abertura || '', agenda: o.data_agenda || '',
            texto: `• *${base}* · O.S. ${id} · ${((n) => n.length > 45 ? n.slice(0, 44) + '…' : n)(nomeCliente[String(o.id_cliente)] || 'cliente ' + o.id_cliente)} · ${nomeAssunto[String(o.id_assunto)] || 'assunto ' + o.id_assunto} · ${detalhe}`,
    };
    const p = porId[`${base}:${tec}`];
    if (p && p.whatsapp) {
      if (!linhasPorPessoa.has(p)) linhasPorPessoa.set(p, []);
      linhasPorPessoa.get(p).push(linha);
    } else {
      const k = p ? `${p.nome} (${base} ${tec})` : `${nomeFunc[tec] || 'id ' + tec} (${base} ${tec})`;
      semCadastro[k] = (semCadastro[k] || 0) + 1;
    }
  }
}

// Mensagens por técnico
const envios = [];
const ordenadas = [...linhasPorPessoa.entries()].sort((a, b) => b[1].length - a[1].length);
for (const [p, linhas] of ordenadas) {
  const semReg = linhas.filter(l => l.tipo === 'sem_registro').sort((a, b) => a.abertura.localeCompare(b.abertura));
  const vencidas = linhas.filter(l => l.tipo === 'agenda_vencida').sort((a, b) => a.agenda.localeCompare(b.agenda));
  const n = linhas.length;
  let resta = cfg.MAX_LINHAS_POR_TECNICO;
  const bloco = (titulo, lista) => {
    if (!lista.length) return [];
    const vis = lista.slice(0, Math.max(resta, 0)); resta -= vis.length;
    const out = ['', titulo, ...vis.map(l => l.texto)];
    if (lista.length > vis.length) out.push(`… e mais ${lista.length - vis.length}`);
    return out;
  };
  const mostrar = [
    ...bloco(`*${semReg.length === 1 ? 'Encaminhada sem registro' : 'Encaminhadas sem registro'} há mais de ${cfg.DIAS_SEM_REGISTRO} dias* – atualize e use o botão *Agendar*:`, semReg),
    ...bloco(`*${vencidas.length === 1 ? 'Agendamento vencido' : 'Agendamentos vencidos'}* – faça um *novo agendamento*:`, vencidas),
  ];
  const basesDele = [...new Set([...semReg, ...vencidas].map(l => l.base))];   // na ordem em que aparecem na mensagem
  const links = basesDele.map(b => LINKS[b]).filter(Boolean);
  const blocoLinks = links.length ? [
    '',
    links.length === 1 ? 'Segue abaixo o link de acesso da base correspondente:' : 'Segue abaixo os links de acesso das bases correspondentes:',
    ...links,
  ] : [];
  const texto = [
    `Bom dia, ${p.nome.split(' ')[0]}!`,
    `Você tem *${n} O.S.* ${n === 1 ? 'que precisa' : 'que precisam'} de atenção:`,
    ...mostrar,
    '',
    'Por favor, atualize o andamento no IXC.',
    ...blocoLinks,
    '',
    '_Aviso automático diário – Resolutto_',
  ].join('\n');
  const porBase = {}; linhas.forEach(l => porBase[l.base] = (porBase[l.base] || 0) + 1);
  envios.push({ tipo: 'tecnico', nome: p.nome, telefone: p.whatsapp, qtd: n, sem_registro: semReg.length, agenda_vencida: vencidas.length, por_base: porBase, texto });
}

// Escala: quem é de escala e não trabalha hoje (ou planilha inconsistente) não recebe
const escala = lerEscala();
const deEscala = new Set(ESCALA.map(e => e.pessoa));
const foraHoje = [];
for (let i = envios.length - 1; i >= 0; i--) {
  const e = envios[i];
  if (deEscala.has(e.nome) && (!escala.ok || !escala.trabalhando.has(e.nome))) { foraHoje.unshift(e); envios.splice(i, 1); }
}
panorama.escala = { ok: escala.ok, detalhe: escala.detalhe, trabalhando_hoje: escala.ok ? [...escala.trabalhando] : [], nao_avisados: foraHoje.map(e => `${e.nome} (${e.qtd})`) };

// Ausências: tira da lista quem está de férias/folga hoje
const hojeISO = DateTime.now().setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
const dataISO = v => { const t = String(v || '').trim(); let m, iso = null;
  if ((m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/))) iso = t;
  else if ((m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/))) iso = `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return iso && DateTime.fromISO(iso).isValid ? iso : null; };
const fmtBR = iso => `${iso.slice(8, 10)}/${iso.slice(5, 7)}`;
const ausentesHoje = new Map();   // nome -> texto do motivo
for (const a of AUSENCIAS) {
  const alvo = norm(a.pessoa);
  const achados = PESSOAS.filter(p => norm(p.nome) === alvo || norm(p.nome).startsWith(alvo + ' '));
  if (!alvo || achados.length === 0) { panorama.avisos.push(`AUSENCIAS: "${a.pessoa}" não encontrado em PESSOAS`); continue; }
  if (achados.length > 1) { panorama.avisos.push(`AUSENCIAS: "${a.pessoa}" é ambíguo (${achados.map(p => p.nome).join(', ')}) — use o nome completo`); continue; }
  const de = dataISO(a.de), ate = a.ate ? dataISO(a.ate) : null;
  const motivo = a.motivo || 'Ausente';
  if (!de || (a.ate && !ate)) {   // data inválida: por segurança considera ausente e avisa
    ausentesHoje.set(achados[0].nome, `${motivo} (data inválida na lista)`);
    panorama.avisos.push(`AUSENCIAS: data inválida para "${a.pessoa}" (use AAAA-MM-DD ou DD/MM/AAAA) — tratado como ausente`);
    continue;
  }
  if (hojeISO >= de && (!ate || hojeISO <= ate)) ausentesHoje.set(achados[0].nome, `${motivo}${ate ? ' até ' + fmtBR(ate) : ''}`);
}
const ausentes = [];
for (let i = envios.length - 1; i >= 0; i--) {
  const e = envios[i];
  if (ausentesHoje.has(e.nome)) { ausentes.unshift({ ...e, motivo: ausentesHoje.get(e.nome) }); envios.splice(i, 1); }
}
for (let i = foraHoje.length - 1; i >= 0; i--) {   // quem já estava fora pela escala e também está ausente: mostra só como ausente
  if (ausentesHoje.has(foraHoje[i].nome)) { ausentes.unshift({ ...foraHoje[i], motivo: ausentesHoje.get(foraHoje[i].nome) }); foraHoje.splice(i, 1); }
}
panorama.escala.nao_avisados = foraHoje.map(e => `${e.nome} (${e.qtd})`);
panorama.ausencias = { hoje: [...ausentesHoje].map(([n, m]) => `${n} – ${m}`), nao_avisados: ausentes.map(e => `${e.nome} (${e.qtd})`) };
// Resumo
const total = envios.reduce((s, e) => s + e.qtd, 0);
const erros = Object.entries(panorama.por_base).filter(([, v]) => v.erro).map(([b, v]) => `${b}: ${v.erro}`);
const resumoLinhas = [
  `*Resumo O.S. paradas – ${cfg.AGORA}*`,
  `${total} O.S. · ${envios.reduce((s, e) => s + e.sem_registro, 0)} encaminhadas sem registro · ${(n => `${n} agend. ${n === 1 ? 'vencido' : 'vencidos'}`)(envios.reduce((s, e) => s + e.agenda_vencida, 0))} · ${envios.length} ${envios.length === 1 ? 'técnico avisado' : 'técnicos avisados'}`,
  '',
  ...envios.map(e => `• ${e.nome}: ${e.qtd} – ${[e.sem_registro ? `${e.sem_registro} sem registro` : '', e.agenda_vencida ? `${e.agenda_vencida} agend. ${e.agenda_vencida === 1 ? 'vencido' : 'vencidos'}` : ''].filter(Boolean).join(', ')} (${Object.entries(e.por_base).map(([b, q]) => `${b} ${q}`).join(', ')})`),
];
if (!escala.ok) resumoLinhas.push('', '⚠️ *Escala com problema:* ' + escala.detalhe, foraHoje.length ? 'Técnicos de escala NÃO avisados hoje: ' + foraHoje.map(e => `${e.nome} (${e.qtd})`).join(', ') : 'Nenhum técnico de escala tinha O.S. para avisar.');
else if (foraHoje.length) resumoLinhas.push('', '*De folga hoje (não avisados):*', ...foraHoje.map(e => `• ${e.nome}: ${e.qtd}`));
if (ausentes.length) resumoLinhas.push('', '*Ausentes (férias/folga) – não avisados:*', ...ausentes.map(e => `• ${e.nome}: ${e.qtd} (${e.motivo})`));
const sc = Object.entries(semCadastro);
if (sc.length) resumoLinhas.push('', '*Sem WhatsApp cadastrado:*', ...sc.map(([k, q]) => `• ${k}: ${q}`));
if (erros.length) resumoLinhas.push('', '*Bases com erro (puladas):*', ...erros.map(e => `• ${e}`));
if (panorama.avisos.length) resumoLinhas.push('', '*Avisos:*', ...panorama.avisos.map(a => `• ${a}`));
const resumo = { tipo: 'resumo', nome: 'Resumo', telefone: cfg.RESUMO_PARA, qtd: total, texto: resumoLinhas.join('\n') };

// Decide o que é enviado
const sd = $getWorkflowStaticData('global');
let motivo = '';
let fila = [];
if (cfg.ENVIO === 'NENHUM') motivo = 'ENVIO = NENHUM (só montagem)';
else if (cfg.ENVIO === 'REAL' && sd.ultimo_envio === cfg.HOJE && !cfg.FORCAR_REENVIO_HOJE) motivo = `já enviado hoje (${cfg.HOJE})`;
else if (cfg.ENVIO === 'REAL' && envios.length + 1 > cfg.MAX_MENSAGENS_DIA) motivo = `${envios.length} mensagens passa de MAX_MENSAGENS_DIA (${cfg.MAX_MENSAGENS_DIA}) — nada enviado`;
else if (cfg.ENVIO === 'SIMULAR') {
  fila = [resumo, ...envios.slice(0, 11).map(e => ({ ...e, telefone: cfg.RESUMO_PARA, texto: `[SIMULAÇÃO → ${e.nome} ${e.telefone}]\n\n${e.texto}` }))];
} else {
  fila = [...(cfg.RESUMO_PARA ? [resumo] : []), ...envios];
  sd.ultimo_envio = cfg.HOJE;
}

const saida = [
  { json: { tipo: 'panorama', enviar: false, envio: cfg.ENVIO, motivo_sem_envio: motivo || null, total_paradas: total, tecnicos: envios.length, ...panorama, sem_whatsapp: semCadastro, resumo_texto: resumo.texto } },
  ...envios.map(e => ({ json: { ...e, enviar: false } })),
];
// itens da fila de envio (enviar: true) — os demais ficam só para conferência
return [...saida, ...fila.filter(f => f.telefone).map(f => ({ json: { ...f, enviar: true } }))];

// Lista os clientes das O.S. que podem entrar no aviso, por base (1 consulta por cliente nos nós "Cliente <BASE>")
const cfg = $('Config').first().json.cfg;
function parse(item) {
  const j = (item && item.json) || {};
  let d = j.data !== undefined ? j.data : j;
  if (typeof d === 'string') { try { d = JSON.parse(d.replace(/[\u0000-\u001F]+/g, ' ')); } catch (e) { return []; } }
  return (d && Array.isArray(d.registros)) ? d.registros : [];
}
const ids = {};
for (const base of cfg.BASES) {
  const set = new Set();
  for (const it of $(`OS ${base}`).all())
    for (const o of parse(it))
      if (String(o.id_tecnico || '0') !== '0' && ['EN', 'AG', 'AN'].includes(o.status) && o.id_cliente && String(o.id_cliente) !== '0') set.add(String(o.id_cliente));
  ids[base] = [...set].slice(0, 300);
}
const n = Math.max(1, ...Object.values(ids).map(a => a.length));
return Array.from({ length: n }, (_, i) => ({ json: { i, ...(i === 0 ? { ids } : {}) } }));

// Diagnóstico de uma O.S.: troque BASE e OS e execute o workflow (ENVIO = 'NENHUM')
const BASE = 'RESOLUTTO', OS = '141';
const cfg = $('Config').first().json.cfg;
function parse(it) { const j = (it && it.json) || {}; let d = j.data !== undefined ? j.data : j; if (typeof d === 'string') { try { d = JSON.parse(d.replace(/[\u0000-\u001F]+/g, ' ')); } catch (e) { return []; } } return (d && Array.isArray(d.registros)) ? d.registros : []; }
const achadas = [];
$(`OS ${BASE}`).all().forEach((it, i) => parse(it).forEach(o => { if (String(o.id) === OS) achadas.push({ assunto_consultado: cfg.ASSUNTOS[BASE][i], id: o.id, status: o.status, id_tecnico: o.id_tecnico, id_assunto: o.id_assunto, data_abertura: o.data_abertura, data_agenda: o.data_agenda, id_cliente: o.id_cliente }); }));
const msgs = parse($(`Msg ${BASE}`).first()).filter(m => String(m.id_chamado) === OS).map(m => ({ data: m.data, mensagem: String(m.mensagem || '').slice(0, 150) }));
const pessoa = cfg.PESSOAS.find(p => (p.ids[BASE] || []).map(String).includes(String((achadas[0] || {}).id_tecnico)));
const naMensagem = $('Montar mensagens').all().filter(i => i.json.tipo === 'tecnico' && String(i.json.texto).includes(`O.S. ${OS} `)).map(i => i.json.nome);
return [{ json: { base: BASE, os: OS, limite_sem_registro: cfg.LIMITE, encontrada_na_leitura: achadas.length > 0, registro: achadas[0] || null, aberta_antes_do_limite: achadas[0] ? achadas[0].data_abertura <= cfg.LIMITE : null, mensagens_ultimos_2_dias: msgs, tecnico_em_PESSOAS: pessoa ? pessoa.nome : 'NÃO ENCONTRADO', esta_na_mensagem_de: naMensagem } }];
